//
//  Feedback.swift
//  "Tac Tile" sound engine: mechanical-switch profiles that pair a click
//  sound with a matching vibration on every key press.
//
//  The sounds are generated by code (no recordings), so they can be tuned
//  by the Custom profile. iOS only lets a keyboard make sound or vibrate
//  when "Allow Full Access" is on, and sounds follow the ring/silent switch.
//

import UIKit
import AudioToolbox

enum SwitchProfile: Int, CaseIterable {
    case blue, brown, red, silent, custom

    var title: String {
        switch self {
        case .blue:   return "Blue"
        case .brown:  return "Brown"
        case .red:    return "Red"
        case .silent: return "Silent"
        case .custom: return "Custom"
        }
    }

    var summary: String {
        switch self {
        case .blue:   return "Blue switch: loud, sharp click with a crisp vibration."
        case .brown:  return "Brown switch: softer tactile bump."
        case .red:    return "Red switch: smooth, quiet, low thud."
        case .silent: return "Silent switch: no sound, light vibration only."
        case .custom: return "Custom: set your own sound and vibration below."
        }
    }
}

final class SwitchFeedback {
    static let shared = SwitchFeedback()

    /// What one key press sounds like. All values 0…1.
    private struct Tone {
        var volume: Double
        var pitch: Double       // low thud … high tick
        var click: Double       // smooth … clicky
    }

    private var keySound: SystemSoundID = 0     // letters, numbers, symbols
    private var bigSound: SystemSoundID = 0     // space, return, delete (deeper)
    private var files: [URL] = []
    private var generation = 0

    private var hapticStyle: UIImpactFeedbackGenerator.FeedbackStyle?
    private var hapticIntensity: CGFloat = 1
    private var generators: [Int: UIImpactFeedbackGenerator] = [:]

    // MARK: Public

    /// Rebuilds the sounds for the chosen profile. Call after settings change.
    func reload(_ settings: KBSettings) {
        dispose()

        let profile = SwitchProfile(rawValue: settings.switchProfile) ?? .brown
        var tone: Tone?
        switch profile {
        case .blue:
            tone = Tone(volume: 0.9, pitch: 0.75, click: 1.0)
            hapticStyle = .rigid
            hapticIntensity = 1.0
        case .brown:
            tone = Tone(volume: 0.75, pitch: 0.45, click: 0.35)
            hapticStyle = .medium
            hapticIntensity = 0.8
        case .red:
            tone = Tone(volume: 0.6, pitch: 0.25, click: 0.05)
            hapticStyle = .soft
            hapticIntensity = 0.7
        case .silent:
            tone = nil
            hapticStyle = .light
            hapticIntensity = 0.5
        case .custom:
            tone = Tone(volume: settings.customVolume, pitch: settings.customPitch,
                        click: settings.customClick)
            switch settings.tapHaptic {
            case 1:  hapticStyle = .light;  hapticIntensity = 0.7
            case 2:  hapticStyle = .medium; hapticIntensity = 0.9
            case 3:  hapticStyle = .heavy;  hapticIntensity = 1.0
            default: hapticStyle = nil
            }
        }

        guard let chosen = tone, chosen.volume > 0.01 else { return }
        generation += 1
        keySound = makeSound(chosen, big: false)
        bigSound = makeSound(chosen, big: true)
    }

    /// Call when a key goes down.
    func keyDown(big: Bool) {
        let sound = big ? bigSound : keySound
        if sound != 0 { AudioServicesPlaySystemSound(sound) }

        if let style = hapticStyle {
            let generator = generators[style.rawValue] ?? UIImpactFeedbackGenerator(style: style)
            generators[style.rawValue] = generator
            generator.impactOccurred(intensity: hapticIntensity)
            generator.prepare()
        }
    }

    // MARK: Sound files

    private func dispose() {
        if keySound != 0 { AudioServicesDisposeSystemSoundID(keySound) }
        if bigSound != 0 { AudioServicesDisposeSystemSoundID(bigSound) }
        keySound = 0
        bigSound = 0
        files.forEach { try? FileManager.default.removeItem(at: $0) }
        files.removeAll()
    }

    private func makeSound(_ tone: Tone, big: Bool) -> SystemSoundID {
        let fm = FileManager.default
        let folder = fm.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? fm.temporaryDirectory
        try? fm.createDirectory(at: folder, withIntermediateDirectories: true)
        let url = folder.appendingPathComponent("switch-\(generation)-\(big ? "big" : "key").wav")

        do {
            try wavData(samples(tone, big: big)).write(to: url, options: .atomic)
        } catch {
            return 0
        }
        files.append(url)

        var id: SystemSoundID = 0
        AudioServicesCreateSystemSoundID(url as CFURL, &id)
        return id
    }

    // MARK: Synthesis

    private let sampleRate = 44_100.0

    /// One key press: a short noise "tick", a low "thock" from the key
    /// bottoming out, and for clicky switches a bright ping plus a second tick.
    private func samples(_ tone: Tone, big: Bool) -> [Int16] {
        let count = Int(sampleRate * 0.07)                 // 70 ms
        let bodyFrequency = (140 + 260 * tone.pitch) * (big ? 0.7 : 1)
        let pingFrequency = 3200 + 2000 * tone.pitch
        let smoothing = 0.15 + 0.85 * tone.click           // lower = duller noise
        let secondTick = 0.018

        var rng = SystemRandomNumberGenerator()
        var filtered = 0.0
        var output = [Int16]()
        output.reserveCapacity(count)

        for i in 0..<count {
            let t = Double(i) / sampleRate

            let white = Double.random(in: -1...1, using: &rng)
            filtered += smoothing * (white - filtered)

            var value = filtered * exp(-t / 0.004) * (0.25 + 0.5 * tone.click)
            value += sin(2 * .pi * bodyFrequency * t) * exp(-t / 0.022) * 0.7
            value += sin(2 * .pi * pingFrequency * t) * exp(-t / 0.006) * 0.8 * tone.click
            if t >= secondTick {
                value += filtered * exp(-(t - secondTick) / 0.003) * 0.4 * tone.click
            }

            let shaped = tanh(value * tone.volume * 1.2)   // gentle limit, no harsh clipping
            output.append(Int16(max(-1, min(1, shaped)) * 32_000))
        }
        return output
    }

    /// Wraps raw samples in a 16-bit mono WAV file.
    private func wavData(_ samples: [Int16]) -> Data {
        func bytes<T: FixedWidthInteger>(_ value: T) -> Data {
            withUnsafeBytes(of: value.littleEndian) { Data($0) }
        }
        let dataSize = UInt32(samples.count * 2)
        let rate = UInt32(sampleRate)

        var data = Data()
        data.append(contentsOf: Array("RIFF".utf8))
        data.append(bytes(UInt32(36) + dataSize))
        data.append(contentsOf: Array("WAVEfmt ".utf8))
        data.append(bytes(UInt32(16)))          // format chunk size
        data.append(bytes(UInt16(1)))           // PCM
        data.append(bytes(UInt16(1)))           // mono
        data.append(bytes(rate))
        data.append(bytes(rate * 2))            // bytes per second
        data.append(bytes(UInt16(2)))           // bytes per sample
        data.append(bytes(UInt16(16)))          // bits per sample
        data.append(contentsOf: Array("data".utf8))
        data.append(bytes(dataSize))
        for sample in samples { data.append(bytes(sample)) }
        return data
    }
}
